package com.jimmy.bluepointer;
import android.content.Context;import android.graphics.*;import android.view.*;import com.google.mlkit.vision.digitalink.recognition.*;
public final class InkPad extends View {
 Paint pen=new Paint(3),grid=new Paint(1);Path path=new Path();Ink.Builder ink=Ink.builder();Ink.Stroke.Builder stroke;public Runnable changed=()->{};public int revision=0;
 public InkPad(Context c){super(c);pen.setColor(AppTheme.INK);pen.setStrokeWidth(6);pen.setStrokeCap(Paint.Cap.ROUND);pen.setStrokeJoin(Paint.Join.ROUND);pen.setStyle(Paint.Style.STROKE);grid.setColor(AppTheme.HAIRLINE);grid.setStrokeWidth(1);setBackgroundColor(AppTheme.SURFACE);setContentDescription("繁體中文手寫區，用手指逐筆寫字");}
 protected void onDraw(Canvas c){super.onDraw(c);c.drawLine(getWidth()/2f,0,getWidth()/2f,getHeight(),grid);c.drawLine(0,getHeight()/2f,getWidth(),getHeight()/2f,grid);c.drawPath(path,pen);}
 public boolean onTouchEvent(MotionEvent e){float x=e.getX(),y=e.getY();int a=e.getActionMasked();if(a==0){getParent().requestDisallowInterceptTouchEvent(true);stroke=Ink.Stroke.builder();stroke.addPoint(Ink.Point.create(x,y,e.getEventTime()));path.moveTo(x,y);revision++;}else if(a==2&&stroke!=null){for(int i=0;i<e.getHistorySize();i++)stroke.addPoint(Ink.Point.create(e.getHistoricalX(i),e.getHistoricalY(i),e.getHistoricalEventTime(i)));stroke.addPoint(Ink.Point.create(x,y,e.getEventTime()));path.lineTo(x,y);}else if(a==1&&stroke!=null){stroke.addPoint(Ink.Point.create(x,y,e.getEventTime()));ink.addStroke(stroke.build());stroke=null;getParent().requestDisallowInterceptTouchEvent(false);changed.run();}else if(a==3){stroke=null;getParent().requestDisallowInterceptTouchEvent(false);}invalidate();return true;}
 public Ink value(){return ink.build();}public void clear(){revision++;path.reset();ink=Ink.builder();stroke=null;invalidate();}
}
